package models

import (
	"time"

	"cctv/shared/pkg/nanoid"

	"gorm.io/gorm"
)

// Notification represents an alert generated by AI or system triggers.
type Notification struct {
	ID           string    `gorm:"primaryKey;type:varchar" json:"id,omitempty"`
	CameraID     string    `gorm:"column:camera_id;type:varchar(21);not null;default:''" json:"camera_id,omitempty"`
	Type         string    `gorm:"column:type;type:varchar(64);not null;default:'person_identified'" json:"type,omitempty"`
	Title        string    `gorm:"column:title;type:varchar(255);not null" json:"title,omitempty"`
	Body         string    `gorm:"column:body;type:text;not null;default:''" json:"body,omitempty"`
	Category     string    `gorm:"column:category;type:varchar(64);not null;default:'family'" json:"category,omitempty"`
	MemberID     string    `gorm:"column:member_id;type:varchar(21);not null;default:''" json:"member_id,omitempty"`
	ThumbnailURL string    `gorm:"column:thumbnail_url;type:text;not null;default:''" json:"thumbnail_url,omitempty"`
	IsRead       bool      `gorm:"column:is_read;not null;default:false" json:"is_read"`
	CreatedAt    time.Time `gorm:"column:created_at;not null;default:CURRENT_TIMESTAMP" json:"created_at,omitempty"`
}

// TableName returns the physical table name in PostgreSQL.
func (Notification) TableName() string {
	return "notifications"
}

// BeforeCreate assigns a new NanoID if none is provided.
func (n *Notification) BeforeCreate(tx *gorm.DB) error {
	if n.ID == "" {
		n.ID = nanoid.New()
	}
	if n.Type == "" {
		n.Type = "person_identified"
	}
	if n.Category == "" {
		n.Category = "family"
	}
	return nil
}
